export function hangLamp(g, x, y, z, { drop = 2 } = {}) {
  if (isAir(g, x, y + 1, z)) throw new Error(`hangLamp at ${x},${y},${z}: no ceiling directly above`);
  if (drop === 2) {
    put(g, x, y, z, ...B.chain("y"));
    put(g, x, y - 1, z, ...B.lantern(true));
  } else {
    put(g, x, y, z, ...B.lantern(true));
  }
}

